  @Test
  def testWriteZipFiles(): Unit = {
    val chunkNameFunzionali = "01234567890_12345678901_202002_F2G_20191103101533_2DP0234.xml"
    val chunkNameStorici = "01234567890_12345678901_202002_S2G_20200226101533_2DP0234.xml"

    val xmlChunksRdd = sc.parallelize(List(
      FileXml(chunkNameFunzionali, new File(s"${ConfigFactory.load.getString("xml.tmpRootPath")}/${FUNZIONALI}/F2G/${chunkNameFunzionali}"),
        List("00000000000000"), outputZipPath = FileUtility.getZipOutputFilePath(chunkNameFunzionali, FUNZIONALI)),
      FileXml(chunkNameStorici, new File(s"${ConfigFactory.load.getString("xml.tmpRootPath")}/${STORICI}/S2G/${chunkNameStorici}"),
        List("00000000000000"), outputZipPath = FileUtility.getZipOutputFilePath(chunkNameStorici, STORICI))))

    FileUtility.writeZipFiles(xmlChunksRdd).count

    Assert.assertTrue(new File(s"${ConfigFactory.load.getString("zip.outputRootPath")}/output_funzionali_20191103101533/F2G/01234567890_12345678901_202002_F2G_20191103101533_2DP0234.zip").exists)
    Assert.assertTrue(new File(s"${ConfigFactory.load.getString("zip.outputRootPath")}/output_storici_20200226101533/S2G/01234567890_12345678901_202002_S2G_20200226101533_2DP0234.zip").exists)

    FileUtils.deleteDirectory(new File(ConfigFactory.load.getString("zip.outputRootPath")))
  }


